ALTER POLICY refund_files_upload ON storage.objects WITH CHECK (bucket_id = 'refund-documents' AND public.refund_allows('refunds.edit') AND split_part(storage.objects.name, '/', 2) IN ('refusal_letter', 'policy') AND array_length(string_to_array(storage.objects.name, '/'), 1) = 3 AND EXISTS (SELECT 1 FROM public.refunds r WHERE r.id::text = split_part(storage.objects.name, '/', 1) AND public.can_see_refund(r.do_user_id)));
ALTER POLICY refund_files_cleanup ON storage.objects USING (bucket_id = 'refund-documents' AND owner = auth.uid() AND public.refund_allows('refunds.edit') AND NOT EXISTS (SELECT 1 FROM public.refund_documents d WHERE d.storage_path = storage.objects.name) AND EXISTS (SELECT 1 FROM public.refunds r WHERE r.id::text = split_part(storage.objects.name, '/', 1) AND public.can_see_refund(r.do_user_id)));